content.content:
1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// statusInStation 表示包裹当前在某站点（已收件或已完成交接）。
15	const statusInStation = "在站"
16	
17	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
18	type Event struct {
19		Op         string    `json:"op"`                   // 收件 | 交接 | 退回
20		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站）
21		Time       time.Time `json:"time"`                 // 发生时间
22		Request    string    `json:"request,omitempty"`    // 交接/退回请求号（收件记录为空）
23		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
24		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）
25		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
26	}
27	
28	// Parcel 是一件包裹的台账信息。
29	type Parcel struct {
30		ID         string    `json:"id"`
31		Station    string    `json:"station"`    // 当前归属站点
32		Status     string    `json:"status"`     // 当前状态
33		Registered time.Time `json:"registered"` // 收件时间
34		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
35	}
36	
37	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
38	type HandoffResult struct {
39		Request    string    `json:"request"`
40		From       string    `json:"from"`
41		To         string    `json:"to"`
42		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
43		Time       time.Time `json:"time"`
44		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
45	}
46	
47	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
48	type ReturnResult struct {
49		Request string    `json:"request"` // 退回请求号
50		Handoff string    `json:"handoff"` // 被退回的原交接请求号
51		From    string    `json:"from"`    // 退回源站（原交接目的站）
52		To      string    `json:"to"`      // 退回目的站（原交接源站）
53		Reason  string    `json:"reason"`
54		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
55		Time    time.Time `json:"time"`
56	}
57	
58	// ledgerFile 是本地数据文件的磁盘结构。
59	type ledgerFile struct {
60		Version  int                       `json:"version"`
61		Parcels  map[string]*Parcel        `json:"parcels"`
62		Handoffs map[string]*HandoffResult `json:"handoffs"`
63		Returns  map[string]*ReturnResult  `json:"returns"`
64	}
65	
66	// Store 是一个数据文件对应的包裹站点交接台账。
67	type Store struct {
68		path string
69		data ledgerFile
70	}
71	
72	var (
73		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
74		ErrCorrupt = errors.New("数据文件已损坏")
75		// ErrNotFound 表示包裹编号在台账中不存在。
76		ErrNotFound = errors.New("包裹不存在")
77	)
78	
79	// Open 打开（或在文件不存在时建立）一个本地台账。
80	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
81	func Open(path string) (*Store, error) {
82		s := &Store{path: path}
83		raw, err := os.ReadFile(path)
84		if err != nil {
85			if os.IsNotExist(err) {
86				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{}, Returns: map[string]*ReturnResult{}}
87				return s, nil
88			}
89			return nil, fmt.Errorf("读取数据文件失败: %w", err)
90		}
91		if len(bytes.TrimSpace(raw)) == 0 {
92			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
93		}
94		if err := json.Unmarshal(raw, &s.data); err != nil {
95			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
96		}
97		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
98			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
99		}
100		// 早期版本的数据文件没有 returns 字段：按空退回表处理，无需手工修改。
101		if s.data.Returns == nil {
102			s.data.Returns = map[string]*ReturnResult{}
103		}
104		if err := s.data.validate(); err != nil {
105			return nil, err
106		}
107		return s, nil
108	}
109	
110	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
111	func (l *ledgerFile) validate() error {
112		for id, p := range l.Parcels {
113			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
114				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
115			}
116			for i, e := range p.Trail {
117				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
118					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
119				}
120				if e.Op == "退回" {
121					if e.Request == "" || e.Reason == "" || e.From == "" {
122						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
123					}
124					if _, ok := l.Handoffs[e.RefRequest]; !ok {
125						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
126					}
127				}
128			}
129		}
130		for req, h := range l.Handoffs {
131			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
132				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
133			}
134			for _, id := range h.Parcels {
135				if _, ok := l.Parcels[id]; !ok {
136					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
137				}
138			}
139			if h.ReturnedBy != "" {
140				r, ok := l.Returns[h.ReturnedBy]
141				if !ok || r.Handoff != req {
142					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
143				}
144			}
145		}
146		for req, r := range l.Returns {
147			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
148				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
149				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
150			}
151			h, ok := l.Handoffs[r.Handoff]
152			if !ok {
153				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
154			}
155			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
156				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
157			}
158			for _, id := range r.Parcels {
159				if _, ok := l.Parcels[id]; !ok {
160					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
161				}
162			}
163		}
164		return nil
165	}
166	
167	// Register 执行单件收件登记并将结果整体落盘。
168	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
169		if _, ok := s.data.Parcels[id]; ok {
170			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
171		}
172		p := &Parcel{
173			ID:         id,
174			Station:    station,
175			Status:     statusInStation,
176			Registered: now,
177			Trail: []Event{{
178				Op:      "收件",
179				Station: station,
180				Time:    now,
181			}},
182		}
183		s.data.Parcels[id] = p
184		if err := s.save(); err != nil {
185			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
186			return nil, err
187		}
188		return p, nil
189	}
190	
191	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
192	func (s *Store) Query(id string) (*Parcel, error) {
193		p, ok := s.data.Parcels[id]
194		if !ok {
195			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
196		}
197		return p, nil
198	}
199	
200	// Handoff 提交一次多件包裹的站点交接。
201	//
202	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
203	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
204	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
205	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
206	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
207		if saved, ok := s.data.Handoffs[request]; ok {
208			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
209				return saved, true, nil
210			}
211			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
212		}
213	
214		// 首次提交：先做全部校验，任何一件不满足都整体失败。
215		for _, id := range parcels {
216			p, ok := s.data.Parcels[id]
217			if !ok {
218				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
219			}
220			if p.Station != from {
221				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
222			}
223		}
224	
225		res := &HandoffResult{
226			Request: request,
227			From:    from,
228			To:      to,
229			Parcels: append([]string(nil), parcels...),
230			Time:    now,
231		}
232		s.data.Handoffs[request] = res
233	
234		// 记录旧值，落盘失败时整体回滚。
235		prev := make(map[string]struct {
236			station string
237			trail   []Event
238		}, len(parcels))
239		for _, id := range parcels {
240			p := s.data.Parcels[id]
241			prev[id] = struct {
242				station string
243				trail   []Event
244			}{p.Station, append([]Event(nil), p.Trail...)}
245			p.Station = to
246			p.Status = statusInStation
247			p.Trail = append(p.Trail, Event{
248				Op:      "交接",
249				Station: to,
250				Request: request,
251				Time:    now,
252			})
253		}
254	
255		if err := s.save(); err != nil {
256			delete(s.data.Handoffs, request)
257			for id, old := range prev {
258				p := s.data.Parcels[id]
259				p.Station = old.station
260				p.Trail = old.trail
261			}
262			return nil, false, err
263		}
264		return res, false, nil
265	}
266	
267	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
268	//
269	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
270	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
271	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
272	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
273	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
274	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
275	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
276	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
277		if saved, ok := s.data.Returns[request]; ok {
278			if saved.Handoff == handoffReq && saved.Reason == reason {
279				return saved, true, nil
280			}
281			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
282				request, saved.Handoff, saved.Reason)
283		}
284	
285		h, ok := s.data.Handoffs[handoffReq]
286		if !ok {
287			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
288		}
289		if h.ReturnedBy != "" {
290			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
291		}
292	
293		// 先做全部校验，任何一件不满足都整批拒绝。
294		for _, id := range h.Parcels {
295			p, ok := s.data.Parcels[id]
296			if !ok {
297				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
298			}
299			if p.Station != h.To || p.Status != statusInStation {
300				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
301					id, p.Station, p.Status, h.To)
302			}
303			last := p.Trail[len(p.Trail)-1]
304			if last.Op != "交接" || last.Request != handoffReq {
305				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
306					id, handoffReq)
307			}
308		}
309	
310		res := &ReturnResult{
311			Request: request,
312			Handoff: handoffReq,
313			From:    h.To,
314			To:      h.From,
315			Reason:  reason,
316			Parcels: append([]string(nil), h.Parcels...),
317			Time:    now,
318		}
319		s.data.Returns[request] = res
320		h.ReturnedBy = request
321	
322		// 记录旧值，落盘失败时整体回滚。
323		prev := make(map[string]struct {
324			station string
325			trail   []Event
326		}, len(h.Parcels))
327		for _, id := range h.Parcels {
328			p := s.data.Parcels[id]
329			prev[id] = struct {
330				station string
331				trail   []Event
332			}{p.Station, append([]Event(nil), p.Trail...)}
333			p.Station = h.From
334			p.Status = statusInStation
335			p.Trail = append(p.Trail, Event{
336				Op:         "退回",
337				Station:    h.From,
338				From:       h.To,
339				Request:    request,
340				RefRequest: handoffReq,
341				Reason:     reason,
342				Time:       now,
343			})
344		}
345	
346		if err := s.save(); err != nil {
347			delete(s.data.Returns, request)
348			h.ReturnedBy = ""
349			for id, old := range prev {
350				p := s.data.Parcels[id]
351				p.Station = old.station
352				p.Trail = old.trail
353			}
354			return nil, false, err
355		}
356		return res, false, nil
357	}
358	
359	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
360	func sameSet(a, b []string) bool {
361		if len(a) != len(b) {
362			return false
363		}
364		x := append([]string(nil), a...)
365		y := append([]string(nil), b...)
366		sort.Strings(x)
367		sort.Strings(y)
368		for i := range x {
369			if x[i] != y[i] {
370				return false
371			}
372		}
373		return true
374	}
375	
376	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
377	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
378	func (s *Store) save() error {
379		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
380			return fmt.Errorf("保存数据文件失败: %w", err)
381		}
382		buf, err := json.MarshalIndent(s.data, "", "  ")
383		if err != nil {
384			return fmt.Errorf("保存数据文件失败: %w", err)
385		}
386		buf = append(buf, '\n')
387	
388		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
389		if err != nil {
390			return fmt.Errorf("保存数据文件失败: %w", err)
391		}
392		tmpName := tmp.Name()
393		cleanup := func() { _ = os.Remove(tmpName) }
394	
395		if _, err := tmp.Write(buf); err != nil {
396			_ = tmp.Close()
397			cleanup()
398			return fmt.Errorf("保存数据文件失败: %w", err)
399		}
400		if err := tmp.Sync(); err != nil {
401			_ = tmp.Close()
402			cleanup()
403			return fmt.Errorf("保存数据文件失败: %w", err)
404		}
405		if err := tmp.Close(); err != nil {
406			cleanup()
407			return fmt.Errorf("保存数据文件失败: %w", err)
408		}
409	
410		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
411		var check ledgerFile
412		if err := json.Unmarshal(buf, &check); err != nil {
413			cleanup()
414			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
415		}
416	
417		if err := os.Rename(tmpName, s.path); err != nil {
418			cleanup()
419			return fmt.Errorf("保存数据文件失败: %w", err)
420		}
421		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
422			_ = dir.Sync()
423			_ = dir.Close()
424		}
425		return nil
426	}
427

