17	func TestHelpVariants(t *testing.T) {
18		for _, args := range [][]string{
19			nil,
20			{"-h"},
21			{"--help"},
22			{"help"},
23			{"register", "--help"},
24			{"handoff", "-h"},
25			{"return", "--help"},
26		} {
27			var out, errb bytes.Buffer
28			code := run(args, &out, &errb)
29			if code != 0 {
30				t.Fatalf("%v 应以 0 退出，得到 %d", args, code)
31			}
32			if !strings.Contains(out.String(), appName) {
33				t.Fatalf("%v 的帮助应包含应用名 %q:\n%s", args, appName, out.String())
34			}
35			if errb.Len() != 0 {
36				t.Fatalf("%v 帮助不应写入 stderr: %s", args, errb.String())
37			}
38		}
39	}
40	
41	func TestUnknownCommandAndArgsExit2(t *testing.T) {
42		dbPath := t.TempDir() + "/ledger.json"
43		cases := [][]string{
44			{"frobnicate"},
45			{"--bogus"},
46			{"register", "--id", "P1", "--station", "A", "extra"},
47			{"register", "--unknown-flag", "x"},
48			{"query", "--id"}, // 缺参数值
49		}
50		for _, c := range cases {
51			var out, errb bytes.Buffer
52			full := append([]string{"--data", dbPath}, c...)
53			code := run(full, &out, &errb)
54			if code != exitUsage {
55				t.Fatalf("%v 应以状态码 2 退出，得到 %d (out=%s err=%s)", c, code, out.String(), errb.String())
56			}
57			if errb.Len() == 0 {
58				t.Fatalf("%v 应在标准错误提示", c)
59			}
60		}
61	}
62	
63	func TestCLIEndToEndRegisterQueryHandoff(t *testing.T) {
64		dbPath := t.TempDir() + "/ledger.json"
65	
66		// 登记两件包裹。
67		out, _, code := runCLI(t, dbPath, "register", "--id", "P001", "--station", "站点A")
68		if code != 0 || !strings.Contains(out, "收件登记成功") || !strings.Contains(out, "在站") {
69			t.Fatalf("登记 P001 失败: code=%d out=%s", code, out)
70		}
71		if _, _, code := runCLI(t, dbPath, "register", "--id", "P002", "--station", "站点A"); code != 0 {
72			t.Fatalf("登记 P002 失败: code=%d", code)
73		}
74	
75		// 重复登记：退出码 1，原记录不变。
76		_, errText, code := runCLI(t, dbPath, "register", "--id", "P001", "--station", "站点B")
77		if code != exitBusiness || !strings.Contains(errText, "已登记") {
78			t.Fatalf("重复登记应失败(1): code=%d err=%s", code, errText)
79		}
80		out, _, code = runCLI(t, dbPath, "query", "--id", "P001")
81		if code != 0 || !strings.Contains(out, "当前站点: 站点A") || strings.Count(out, "收件") != 1 {
82			t.Fatalf("重复登记不得改变原记录: code=%d out=%s", code, out)
83		}
84	
85		// 查询不存在的包裹：报错、退出 1。
86		_, errText, code = runCLI(t, dbPath, "query", "--id", "GHOST")
87		if code != exitBusiness || !strings.Contains(errText, "包裹不存在") {
88			t.Fatalf("查询不存在包裹应报错(1): code=%d err=%s", code, errText)
89		}
90	
91		// 交接：一件包裹不在源站点，整次失败，所有包裹不变。
92		_, errText, code = runCLI(t, dbPath, "handoff",
93			"--request", "RBAD", "--from", "站点A", "--to", "站点B",
94			"--parcel", "P001", "--parcel", "GHOST")
95		if code != exitBusiness || !strings.Contains(errText, "整次交接未执行") {
96			t.Fatalf("含未登记包裹的交接应整体失败: code=%d err=%s", code, errText)
97		}
98		out, _, _ = runCLI(t, dbPath, "query", "--id", "P001")
99		if !strings.Contains(out, "当前站点: 站点A") || strings.Contains(out, "交接") {
100			t.Fatalf("失败交接不得改动 P001: %s", out)
101		}
102		// 失败不占用请求号：纠正后同号可成功。
103		out, _, code = runCLI(t, dbPath, "handoff",
104			"--request", "RBAD", "--from", "站点A", "--to", "站点B",
105			"--parcel", "P001", "--parcel", "P002")
106		if code != 0 || !strings.Contains(out, "交接成功") || strings.Contains(out, "返回首次保存的结果") {
107			t.Fatalf("纠正后交接应成功: code=%d out=%s", code, out)
108		}
109	
110		// 查询轨迹：收件 + 交接，交接记录带请求号。
111		out, _, code = runCLI(t, dbPath, "query", "--id", "P001")
112		if code != 0 {
113			t.Fatalf("查询失败: %d", code)
114		}
115		if !strings.Contains(out, "当前站点: 站点B") ||
116			!strings.Contains(out, "1. 操作: 收件") ||
117			!strings.Contains(out, "2. 操作: 交接") ||
118			!strings.Contains(out, "请求号: RBAD") {
119			t.Fatalf("轨迹展示不符:\n%s", out)
120		}
121	
122		// 同请求号、同内容、集合换序：重放首次结果，不追加轨迹。
123		out, _, code = runCLI(t, dbPath, "handoff",
124			"--request", "RBAD", "--from", "站点A", "--to", "站点B",
125			"--parcel", "P002", "--parcel", "P001")
126		if code != 0 || !strings.Contains(out, "返回首次保存的结果") {
127			t.Fatalf("重复请求应重放: code=%d out=%s", code, out)
